<div class="flex items-center gap-2"><x-capstone::icon name="Calendar" class="h-5 w-5 shrink-0" /><span x-text="date(schedule?.date)"></span></div><div class="flex items-center gap-2"><x-capstone::icon name="Clock" class="h-5 w-5 shrink-0" /><span x-text="(schedule?.start_time || '')+' - '+(schedule?.end_time || '')"></span></div><div class="flex items-center gap-2"><x-capstone::icon name="MapPin" class="h-5 w-5 shrink-0" /><span x-text="schedule?.room"></span></div>
